/**
 * Everything the progress screen shows, read from IndexedDB in one pass so
 * the numbers on screen are internally consistent.
 */
import {
  dayIndex,
  effectiveStreak,
  forecast,
  historyWindow,
  overview,
  type DayStat,
  type ForecastDay,
  type Overview,
  type Streak,
} from '@lexpad/core';
import { loadHistory, loadSchedule, loadStreak, inView, wordsInView } from '@/db/repo.js';
import { localTimeZone } from '@/lib/format.js';
import { loadSrsView, type SrsView } from '@/features/schedule/data.js';

/** How many days the chart shows, as the prototype does. */
export const CHART_DAYS = 14;

export interface ProgressData extends Overview {
  /** Words that have been reviewed at least once. */
  started: number;
  streak: Streak;
  streakActive: boolean;
  /** Oldest first, always exactly CHART_DAYS long. */
  history: Required<DayStat>[];
  today: number;
  hasNotebook: boolean;
  /** What SRS v2 shows here (the forecast and true retention are its features). */
  srs: SrsView;
  /** The notebooks in view, for the server's per-notebook counts. */
  notebookIds: string[];
  /** Reviews planned for the next 30 days, today first (SRS v2 phase D). */
  forecast: ForecastDay[];
  /** Whether the notebooks in view use Boxes, Smart, or both. */
  schedulers: { boxes: boolean; smart: boolean };
  /** Smart's target when every notebook in view is Smart with the same one. */
  smartTarget: number | undefined;
}

const EMPTY: Overview = {
  totalWords: 0,
  mastered: 0,
  boxes: [0, 0, 0, 0, 0],
  accuracyByCategory: [],
};

export async function loadProgress(now: Date = new Date()): Promise<ProgressData> {
  const timeZone = localTimeZone();
  const today = dayIndex(now, timeZone);
  /*
   * What is in view, not whichever notebook happens to be active. With
   * every notebook chosen, this screen used to show the active one's words
   * alone -- so making a new notebook, which makes it active, emptied
   * Progress even though the setting said to show everything.
   */
  const { showing, notebooks } = await inView();
  const streak = await loadStreak();
  const stats = await loadHistory(CHART_DAYS, timeZone, now);

  const words = notebooks.length > 0 ? await wordsInView() : [];
  const hasNotebook = showing !== undefined || notebooks.length > 0;
  const [srs, schedules] = await Promise.all([
    loadSrsView(),
    Promise.all(notebooks.map(async (notebook) => [notebook.id, await loadSchedule(notebook.id)] as const)),
  ]);
  const byNotebook = new Map(schedules);
  const smartIn = (notebookId: string): boolean => byNotebook.get(notebookId)?.scheduler === 'smart';
  const targets = new Set(
    schedules.map(([, schedule]) => (schedule.scheduler === 'smart' ? schedule.retention : -1)),
  );
  const only = targets.size === 1 ? [...targets][0] : undefined;

  return {
    ...(hasNotebook ? overview(words) : EMPTY),
    started: words.filter((word) => (word.progress?.reps ?? 0) > 0).length,
    streak,
    streakActive: effectiveStreak(streak, today) > 0,
    history: historyWindow(stats, today, CHART_DAYS),
    today,
    hasNotebook,
    srs,
    notebookIds: notebooks.map((notebook) => notebook.id),
    forecast: forecast(
      words.map((word) => ({ progress: word.progress, smart: smartIn(word.notebookId) })),
      today,
    ),
    schedulers: {
      boxes: schedules.some(([, schedule]) => schedule.scheduler !== 'smart'),
      smart: schedules.some(([, schedule]) => schedule.scheduler === 'smart'),
    },
    smartTarget: only !== undefined && only > 0 ? only : undefined,
  };
}
