import { useId, useState } from 'react';
import { forecastTotal, type ForecastDay } from '@lexpad/core';
import { EmptyState } from '@/components/ui/EmptyState.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { shortDate } from '@/features/schedule/nextCheck.js';
import styles from './Forecast.module.css';

/** The days under the bars that carry a label: today, then each week. */
const TICKS = [0, 7, 14, 21, 29];

/**
 * The next 30 days (SRS v2 phase D, spec §6.8): one bar per day of the
 * reviews already planned, today first with everything late in it. Bars are
 * gold for Boxes notebooks and accent for Smart ones, stacked when both are
 * in view, with a legend then so no colour carries meaning alone.
 *
 * The chart is one control, a slider over the days: arrows (Home/End) move
 * through them and the line above the bars reads the day out, as does a
 * pointer over a bar or a tap. That keeps one tab stop and big targets on a
 * phone, where thirty bars are each a few pixels wide. The same numbers are
 * a table, hidden for screen readers until the toggle shows it to everyone.
 */
export function Forecast({
  days,
  schedulers,
}: {
  days: readonly ForecastDay[];
  schedulers: { boxes: boolean; smart: boolean };
}): React.JSX.Element {
  const id = useId();
  const [index, setIndex] = useState(0);
  const [showTable, setShowTable] = useState(false);
  const total = forecastTotal(days);
  const busiest = Math.max(1, ...days.map((day) => day.boxes + day.smart));
  const both = schedulers.boxes && schedulers.smart;
  const today = days[0]?.day ?? 0;

  const dayName = (day: ForecastDay): string =>
    day.day === today
      ? t('forecast.today')
      : day.day === today + 1
        ? t('forecast.tomorrow')
        : shortDate(day.day);
  const reading = (day: ForecastDay): string => {
    const count = day.boxes + day.smart;
    const parts = [t('forecast.reviews', { day: dayName(day), count })];
    if (day.overdue > 0) parts.push(t('forecast.late', { count: day.overdue }));
    if (both && count > 0) parts.push(t('forecast.split', { boxes: day.boxes, smart: day.smart }));
    return parts.join(' ');
  };
  const current = days[Math.min(index, days.length - 1)];

  if (total === 0) {
    return (
      <EmptyState
        compact
        icon="progress"
        tone="quiet"
        title={t('forecast.emptyTitle')}
        body={t('forecast.empty')}
      />
    );
  }

  const move = (next: number): void => {
    setIndex(Math.max(0, Math.min(days.length - 1, next)));
  };

  return (
    <div className={styles.panel}>
      <p className={styles.readout} aria-hidden="true">
        {current !== undefined ? reading(current) : ''}
      </p>
      <div
        className={styles.chart}
        role="slider"
        tabIndex={0}
        aria-label={t('forecast.chart')}
        aria-valuemin={1}
        aria-valuemax={days.length}
        aria-valuenow={index + 1}
        aria-valuetext={current !== undefined ? reading(current) : ''}
        onKeyDown={(event) => {
          const step = { ArrowRight: 1, ArrowUp: 1, ArrowLeft: -1, ArrowDown: -1 }[event.key];
          if (step !== undefined) {
            event.preventDefault();
            move(index + step);
          } else if (event.key === 'Home') {
            event.preventDefault();
            move(0);
          } else if (event.key === 'End') {
            event.preventDefault();
            move(days.length - 1);
          } else if (event.key === 'PageUp' || event.key === 'PageDown') {
            event.preventDefault();
            move(index + (event.key === 'PageUp' ? 7 : -7));
          }
        }}
        onPointerMove={(event) => {
          const box = event.currentTarget.getBoundingClientRect();
          if (box.width > 0) move(Math.floor(((event.clientX - box.left) / box.width) * days.length));
        }}
        onPointerDown={(event) => {
          const box = event.currentTarget.getBoundingClientRect();
          if (box.width > 0) move(Math.floor(((event.clientX - box.left) / box.width) * days.length));
        }}
      >
        {days.map((day, i) => {
          const count = day.boxes + day.smart;
          return (
            <span key={day.day} className={cx(styles.day, i === index && styles.dayOn)} aria-hidden="true">
              <span className={styles.column}>
                {count === 0 ? (
                  <span className={styles.stub} />
                ) : (
                  <span
                    className={styles.stack}
                    style={{ height: `${String(Math.max((count / busiest) * 100, 6))}%` }}
                  >
                    {day.smart > 0 && <span className={styles.smart} style={{ flexGrow: day.smart }} />}
                    {day.boxes > 0 && <span className={styles.boxes} style={{ flexGrow: day.boxes }} />}
                  </span>
                )}
              </span>
            </span>
          );
        })}
      </div>
      <div className={styles.ticks} aria-hidden="true">
        {TICKS.filter((tick) => tick < days.length).map((tick) => {
          const day = days[tick];
          return day === undefined ? null : (
            <span
              key={tick}
              className={cx(
                styles.tick,
                tick === 0 && styles.tickStart,
                tick === days.length - 1 && styles.tickEnd,
              )}
              style={
                tick === 0 || tick === days.length - 1
                  ? undefined
                  : { left: `${String(((tick + 0.5) / days.length) * 100)}%` }
              }
            >
              {tick === 0 ? t('forecast.today') : shortDate(day.day)}
            </span>
          );
        })}
      </div>
      {both && (
        <p className={styles.legend}>
          <span className={styles.key}>
            <span className={cx(styles.swatch, styles.boxes)} aria-hidden="true" />
            {t('forecast.boxes')}
          </span>
          <span className={styles.key}>
            <span className={cx(styles.swatch, styles.smart)} aria-hidden="true" />
            {t('forecast.smart')}
          </span>
        </p>
      )}
      <p className={styles.note}>{t('forecast.note')}</p>
      <button
        type="button"
        className={styles.toggle}
        aria-expanded={showTable}
        aria-controls={`${id}-table`}
        onClick={() => {
          setShowTable((open) => !open);
        }}
      >
        {showTable ? t('forecast.hideTable') : t('forecast.showTable')}
      </button>
      <table id={`${id}-table`} className={showTable ? styles.table : 'sr-only'}>
        <caption className="sr-only">{t('forecast.caption')}</caption>
        <thead>
          <tr>
            <th scope="col">{t('forecast.colDay')}</th>
            <th scope="col">{t('forecast.colReviews')}</th>
            {both && <th scope="col">{t('forecast.boxes')}</th>}
            {both && <th scope="col">{t('forecast.smart')}</th>}
          </tr>
        </thead>
        <tbody>
          {days.map((day) => (
            <tr key={day.day}>
              <th scope="row">{dayName(day)}</th>
              <td>
                {day.overdue > 0
                  ? t('forecast.cellLate', { count: day.boxes + day.smart, late: day.overdue })
                  : day.boxes + day.smart}
              </td>
              {both && <td>{day.boxes}</td>}
              {both && <td>{day.smart}</td>}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
