import { Skeleton } from '@/components/ui/Skeleton.js';
import { t } from '@/i18n/index.js';
import { relativeTimeInline } from '@/lib/format.js';
import { retentionFor, type StatsFetch, type StoredSrsStats } from '@/features/schedule/stats.js';
import styles from './Retention.module.css';

/**
 * "Remembered when due" (SRS v2 phase D, spec §6.8): of the first answers
 * to words that were due in the last 30 days, the share that were right,
 * over the notebooks in view. The server counts them from every device's
 * answers; this shows its copy, says "as of" when it could not read a new
 * one, and says so plainly when it never could. Below twenty answers it says
 * there are not enough yet rather than print a figure one answer can swing.
 */
export function Retention({
  stored,
  ready,
  fetch,
  notebookIds,
  target,
}: {
  stored: StoredSrsStats | null;
  /** The local copy has been read (it may be empty). */
  ready: boolean;
  fetch: StatsFetch;
  notebookIds: readonly string[];
  /** Smart's target, when every notebook in view shares one. */
  target: number | undefined;
}): React.JSX.Element {
  if (!ready || (stored === null && fetch === 'idle')) {
    return (
      <div className={styles.card}>
        <Skeleton lines={2} />
        <span className="sr-only" role="status">
          {t('state.loading')}
        </span>
      </div>
    );
  }
  if (stored === null) {
    return (
      <div className={styles.card}>
        <p className={styles.quiet}>{fetch === 'offline' ? t('retention.offline') : t('retention.failed')}</p>
      </div>
    );
  }
  const share = retentionFor(stored, notebookIds);
  const stale = fetch === 'offline' || fetch === 'failed';
  return (
    <div className={styles.card}>
      <div className={styles.top}>
        {share.percent === null ? (
          <p className={styles.notYet}>{t('retention.notEnough')}</p>
        ) : (
          <p className={styles.value}>
            <span aria-hidden="true">{t('retention.percent', { percent: share.percent })}</span>
            <span className="sr-only">{t('retention.percentSpoken', { percent: share.percent })}</span>
          </p>
        )}
        <div className={styles.words}>
          <p className={styles.meta}>
            {target === undefined
              ? t('retention.window', { days: stored.stats.days })
              : t('retention.windowTarget', { days: stored.stats.days, target })}
          </p>
        </div>
      </div>
      <p className={styles.explain}>
        {share.percent === null ? t('retention.notEnoughBody') : t('retention.explain')}
      </p>
      {stale && (
        <p className={styles.asOf}>
          {t(fetch === 'offline' ? 'retention.asOfOffline' : 'retention.asOf', {
            when: relativeTimeInline(stored.at),
          })}
        </p>
      )}
    </div>
  );
}
